fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // For each parent index i, check the min-heap property against children.
    // Only need to check up to the last parent node, which is floor(n/2) - 1.
    let last_parent = n / 2;

    for i in 0..last_parent {
        let left = 2 * i + 1;
        let right = 2 * i + 2;

        // Check left child if it exists
        if left < n && a[i] > a[left] {
            return false;
        }
        // Check right child if it exists
        if right < n && a[i] > a[right] {
            return false;
        }
    }

    true
}